using System;using LWS.TruckBeerPong;
public class PongFixtures{public static void Main(){int checks=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Pong rules: "+label);checks++;};var r=new PongRules();r.Reset(2,2);check(r.Shooter==0&&r.NextTeammate==1&&r.remaining[0]==10&&r.remaining[1]==10,"2v2 initial rack/shooter");check(!r.Advance()&&!r.TryHit(0,0),"no unresolved turn advance or own cup score");check(r.TryHit(1,0)&&!r.TryHit(1,1)&&!r.Miss()&&r.remaining[1]==9,"one cup maximum per delivery");r.Advance();check(r.ActiveTeam==1&&r.Shooter==2,"normal hit still alternates teams");r.Miss();r.Advance();check(r.ActiveTeam==0&&r.Shooter==1,"normal miss alternates; teammates rotate");check(!r.TryHit(1,0)&&!r.ShotLocked,"removed cup cannot score again");r.Reset(1,1);for(int i=0;i<10;i++){check(r.ActiveTeam==0&&r.TryHit(1,i),"clear actual remaining opposing cup");r.Advance();if(i<9){check(r.Period==PongPeriod.Normal&&r.ActiveTeam==1,"no early rebuttal");r.Miss();r.Advance();}}check(!r.Complete&&r.Period==PongPeriod.Rebuttal&&r.ActiveTeam==1,"final cup grants opponent rebuttal");r.Miss();r.Advance();check(r.Complete&&r.Winner==0&&!r.Miss()&&!r.TryHit(0,0)&&!r.Advance(),"first rebuttal miss loses once");r.Reset(2,2);for(int i=0;i<10;i++){r.TryHit(1,i);r.Advance();if(i<9){r.Miss();r.Advance();}}int previous=r.Shooter;for(int i=0;i<10;i++){check(r.TryHit(0,i),"rebuttal valid catch");r.Advance();if(i<9){check(r.ActiveTeam==1&&r.Period==PongPeriod.Rebuttal&&r.Shooter!=previous,"rebuttal keeps team and alternates teammates");previous=r.Shooter;}}check(r.Overtime==1&&r.Period==PongPeriod.Normal&&r.remaining[0]==3&&r.remaining[1]==3&&r.ActiveTeam==1,"successful rebuttal starts three-cup overtime; opposite first team");for(int overtime=1;overtime<=3;overtime++){int first=r.ActiveTeam;for(int cup=0;cup<3;cup++){check(r.TryHit(1-first,cup),"overtime uses three remaining cups");r.Advance();if(cup<2){r.Miss();r.Advance();}}check(r.Period==PongPeriod.Rebuttal&&r.ActiveTeam==1-first,"overtime also grants rebuttal");for(int cup=0;cup<3;cup++){r.TryHit(first,cup);r.Advance();}check(r.Overtime==overtime+1&&r.ActiveTeam==1-first&&r.remaining[0]==3&&r.remaining[1]==3,"repeated overtime alternates first team");}
 r.Reset(1,1,true);for(int rack=0;rack<2;rack++)for(int cup=0;cup<10;cup++){check(r.ActiveTeam==0&&r.Shooter==0&&r.TryHit(1,cup),"solo practice ordinary cup lock");r.Advance();}check(!r.Complete&&r.PracticeRacks==2&&r.remaining[1]==10&&r.shots[0]==20&&r.hits[0]==20,"practice reracks only after clearing and keeps statistics");System.IO.Directory.CreateDirectory("Logs/TruckSports/SevenSports");System.IO.File.WriteAllText("Logs/TruckSports/SevenSports/pong-rules-result.txt","PASS "+checks+" pure house-rule checks; physical gameplay is separate");UnityEngine.Debug.Log("PONG_RULE_FIXTURES_PASS "+checks);}}
